// Validation
type Path = ReadonlyArray<PropertyKey>;

export interface Issue {
	readonly message: string;
	readonly path?: Path;
	readonly code?: string;
}
type Issueish = Issue['message'] | Issue;

export type Validated<Out> =
	| { readonly data: Out; readonly validation?: never }
	| { readonly data: unknown; readonly validation: Validation<Out> };

interface Constraint {
	issue: Issueish;
}
interface CustomConstraint {
	validate: (input: unknown) => Validation<unknown>;
}

interface StringConstraints {
	length?: { min?: number; max?: number } & Constraint;
	match?: { regexp: RegExp } & Constraint;
	list?: { values: Iterable<string> } & Constraint;
	custom?: CustomConstraint;
}

interface ObjectConstraints {
	custom?: CustomConstraint;
}

interface NumberConstraints {
	range?: { min?: number; max?: number } & Constraint;
	list?: { values: Iterable<number> } & Constraint;
	custom?: CustomConstraint;
}

interface DateConstraints {
	range?: { min?: Date; max?: Date } & Constraint;
	custom?: CustomConstraint;
}

export class Validation<Out> {
	/**
	 * Tests whether a result is invalid. Kind of weird that it’s the negative,
	 * but most usage will be to handle a `Validated`’s invalid state.
	 */
	static is_invalid(result: unknown): result is { readonly validation: Validation<unknown> } {
		return (
			undefined !== result &&
			null !== result &&
			'object' === typeof result &&
			'validation' in result &&
			result.validation instanceof Validation
		);
	}

	#issues: Issue[] = [];
	/**
	 * Namespace for existence/type checks. `is_*` methods check the primitive type and assert the type.
	 * If it’s not, adds an issue to the current instance. `has_*` methods do the same,
	 * but for a property on the `input`.
	 */
	readonly test;
	constructor() {
		const that = this;
		this.test = {
			/**
			 * @param input What’s being validated.
			 * @param issue The issue to capture if the validation fails. Generally this will just be a `string` message.
			 *              Pass a full `Issue` (rather than just a message) if the caller needs a specific `path` or `code`.
			 * @param constraints Optional declarative validation rules. These are ANDed together.
			 * @returns A type guard that `input` is a non-`null` object.
			 */
			is_object(
				input: unknown,
				issue: Issueish,
				constraints: ObjectConstraints = {}
			): input is Record<string, unknown> {
				if (undefined === input || null === input || 'object' !== typeof input) {
					that.add(issue);
					return false;
				}
				const local = new Validation();

				// custom
				if (constraints.custom) {
					local.merge(constraints.custom.validate(input));
				}
				that.merge(local);
				return !local.has();
			},
			/**
			 * Delegates to `is_object` against a scratch `Validation` instance, then merges its
			 * issues (the missing/wrong-type check, plus any constraint failures) into this
			 * instance scoped under `key` — so every issue produced for this property, however
			 * many constraints fired, lands at the same `[key]` path.
			 */
			has_object<T extends object, K extends string>(
				input: T,
				key: K,
				issue: Issueish,
				constraints: ObjectConstraints = {}
			): input is T & Record<K, Record<string, unknown>> {
				const local = new Validation();
				if (undefined === input || null === input) {
					local.add(issue);
				} else {
					local.test.is_object((input as Record<string, unknown>)[key], issue, constraints);
				}
				that.merge(local, [key]);
				return !local.has();
			},

			/**
			 *
			 * @param input What’s being validated. Note that validationdoesn]t do any parsing or formatting.
			 *              Those need to be handled up- and downstream, respectively.
			 * @param issue The issue to capture if the validation fails. Generally this will just be a `string` message.
			 *              Pass a full `Issue` (rather than just a message) if the caller needs a specific `path` or `code`.
			 * @param constraints Optional declarative validation rules. These are ANDed together.
			 * @returns A type guard that `input` is, in fact, a `string`. This is not _really_ true
			 *          because that validation here can be much more strict than any `string`,
			 *          e.g. length or regular expression matching. However, downstream should continue to treat
			 *          the `input` as invalid and thus `unknown` typed.
			 *
			 * @example ```
			 *   if(validateion.test.is_string(input, '«This value» must exist and be a string')) {
			 *     // Other validation or formatting logic can now safely assume that `input` is a `string`
			 *   }
			 * ```
			 * @example ```
			 *   if(validateion.test.is_string(input, '…'), {length: {min: 3, issue: 'At least 3'}}) {
			 *     // `input` is `string` and at least three characters in length
			 *   }
			 * ```
			 */
			is_string(
				input: unknown,
				issue: Issueish,
				constraints: StringConstraints = {}
			): input is string {
				if (undefined === input || null === input || 'string' !== typeof input) {
					that.add(issue);
					return false;
				}
				const local = new Validation();

				// length
				if (constraints.length) {
					if (
						input.length < (constraints.length.min ?? Number.NEGATIVE_INFINITY) ||
						input.length > (constraints.length.max ?? Number.POSITIVE_INFINITY)
					) {
						local.add(constraints.length.issue);
					}
				}
				// match
				if (constraints.match) {
					if (!constraints.match.regexp.test(input)) {
						local.add(constraints.match.issue);
					}
				}
				// list
				if (constraints.list) {
					if (!new Set(constraints.list.values).has(input)) {
						local.add(constraints.list.issue);
					}
				}
				// custom
				if (constraints.custom) {
					local.merge(constraints.custom.validate(input));
				}
				that.merge(local);
				return !local.has();
			},
			/**
			 * Delegates to `is_string` against a scratch `Validation` instance, then merges its
			 * issues (the missing/wrong-type check, plus any constraint failures) into this
			 * instance scoped under `key` — so every issue produced for this property, however
			 * many constraints fired, lands at the same `[key]` path.
			 */
			has_string<T extends object, K extends string>(
				input: T,
				key: K,
				issue: Issueish,
				constraints: StringConstraints = {}
			): input is T & Record<K, string> {
				const local = new Validation();
				if (undefined === input || null === input) {
					local.add(issue);
				} else {
					local.test.is_string((input as Record<string, unknown>)[key], issue, constraints);
				}
				that.merge(local, [key]);
				return !local.has();
			},
			/**
			 * @param input What’s being validated.
			 * @param issue The issue to capture if the validation fails. Generally this will just be a `string` message.
			 *              Pass a full `Issue` (rather than just a message) if the caller needs a specific `path` or `code`.
			 * @param constraints Optional declarative validation rules. These are ANDed together.
			 * @returns A type guard that `input` is a `number` (excluding `NaN`).
			 */
			is_number(
				input: unknown,
				issue: Issueish,
				constraints: NumberConstraints = {}
			): input is number {
				if (
					undefined === input ||
					null === input ||
					'number' !== typeof input ||
					Number.isNaN(input)
				) {
					that.add(issue);
					return false;
				}
				const local = new Validation();

				// range
				if (constraints.range) {
					if (
						input < (constraints.range.min ?? Number.NEGATIVE_INFINITY) ||
						input > (constraints.range.max ?? Number.POSITIVE_INFINITY)
					) {
						local.add(constraints.range.issue);
					}
				}
				// list
				if (constraints.list) {
					if (!new Set(constraints.list.values).has(input)) {
						local.add(constraints.list.issue);
					}
				}
				// custom
				if (constraints.custom) {
					local.merge(constraints.custom.validate(input));
				}
				that.merge(local);
				return !local.has();
			},
			/**
			 * Delegates to `is_number` against a scratch `Validation` instance, then merges its
			 * issues (the missing/wrong-type check, plus any constraint failures) into this
			 * instance scoped under `key` — so every issue produced for this property, however
			 * many constraints fired, lands at the same `[key]` path.
			 */
			has_number<T extends object, K extends string>(
				input: T,
				key: K,
				issue: Issueish,
				constraints: NumberConstraints = {}
			): input is T & Record<K, number> {
				const local = new Validation();
				if (undefined === input || null === input) {
					local.add(issue);
				} else {
					local.test.is_number((input as Record<string, unknown>)[key], issue, constraints);
				}
				that.merge(local, [key]);
				return !local.has();
			},
			/**
			 * @param input What’s being validated.
			 * @param issue The issue to capture if the validation fails. Generally this will just be a `string` message.
			 *              Pass a full `Issue` (rather than just a message) if the caller needs a specific `path` or `code`.
			 * @param constraints Optional declarative validation rules. These are ANDed together.
			 * @returns A type guard that `input` is a valid `Date` (excluding `Invalid Date`).
			 */
			is_date(input: unknown, issue: Issueish, constraints: DateConstraints = {}): input is Date {
				if (
					undefined === input ||
					null === input ||
					!(input instanceof Date) ||
					Number.isNaN(input.getTime())
				) {
					that.add(issue);
					return false;
				}
				const local = new Validation();

				// range
				if (constraints.range) {
					if (
						(undefined !== constraints.range.min && input < constraints.range.min) ||
						(undefined !== constraints.range.max && input > constraints.range.max)
					) {
						local.add(constraints.range.issue);
					}
				}
				// custom
				if (constraints.custom) {
					local.merge(constraints.custom.validate(input));
				}
				that.merge(local);
				return !local.has();
			},
			/**
			 * Delegates to `is_date` against a scratch `Validation` instance, then merges its
			 * issues (the missing/wrong-type check, plus any constraint failures) into this
			 * instance scoped under `key` — so every issue produced for this property, however
			 * many constraints fired, lands at the same `[key]` path.
			 */
			has_date<T extends object, K extends string>(
				input: T,
				key: K,
				issue: Issueish,
				constraints: DateConstraints = {}
			): input is T & Record<K, Date> {
				const local = new Validation();
				if (undefined === input || null === input) {
					local.add(issue);
				} else {
					local.test.is_date((input as Record<string, unknown>)[key], issue, constraints);
				}
				that.merge(local, [key]);
				return !local.has();
			}
		};
	}

	add(...issues: Issueish[]): this {
		for (const issue of issues) {
			if ('string' === typeof issue) this.#issues.push({ message: issue, path: [] });
			else this.#issues.push(issue);
		}
		return this;
	}

	/**
	 * Adds `issues`’ issues to this instance’s issues at a path relative to `base_path`.
	 * Accepts any `Iterable<Issue>` — a `Validation` instance qualifies via `Symbol.iterator`,
	 * but so does a plain array, which is what makes `fromJSON` possible without an unsafe cast.
	 */
	merge(issues: Iterable<Issue>, base_path: Path = []): this {
		for (const issue of issues) {
			this.#issues.push({
				message: issue.message,
				path: [...base_path, ...(issue.path ?? [])],
				code: issue.code
			});
		}
		return this;
	}

	issues(path?: Path | string, code?: Issue['code']): ReadonlyArray<Issue> {
		let found: ReadonlyArray<Issue> = this.#issues;
		if (undefined !== path) {
			const _path = 'string' === typeof path ? ('' === path ? [] : [path]) : path;
			found = found.filter((issue) => {
				if (_path.length !== issue.path?.length) return false;
				for (let i = 0; i < _path.length; i++) {
					if (_path[i] !== issue.path?.[i]) return false;
				}
				return true;
			});
		}
		if (undefined !== code) {
			found = found.filter((issue) => issue.code === code);
		}
		return found;
	}

	at(index: number): Issue | undefined {
		return this.#issues.at(index);
	}

	first(path?: Path | string, code?: Issue['code']): Issue | undefined {
		return this.issues(path, code)[0];
	}

	/**
	 * Existence of any issues filtered by `path` and `code`
	 */
	has(path?: Path | string, code?: Issue['code']): boolean {
		return this.issues(path, code).length > 0;
	}

	/**
	 * Filters by `code`.
	 *
	 * @see Validation#has()
	 */
	coded(code?: Issue['code']): boolean {
		return this.has(undefined, code);
	}

	/**
	 * Loops through a `collection` and validates each item, adding to this instance’s issues.
	 * If any are invalid, return a snapshot of the original items. Otherwise, the validated output’s `data`.
	 *
	 * `collection` is only ever iterated once — the returned snapshot is what gets handed back on
	 * the invalid path, rather than the original `collection`, so a one-shot `Iterable` (a generator,
	 * say) doesn’t come back exhausted.
	 */
	collect<In, Out>(
		collection: Iterable<In>,
		validate: (item: In) => Validated<Out>,
		base_path: Path = []
	): Iterable<In | Out> {
		let dirty = false;
		const items = Array.from(collection);
		const output = items.map((item, index) => {
			const result = validate(item);
			if (Validation.is_invalid(result)) {
				dirty = true;
				this.merge(result.validation, [...base_path, index]);
				return item;
			}
			return result.data;
		});
		if (dirty) return items;
		return output;
	}

	toJSON(): readonly Issue[] {
		return this.#issues;
	}

	static fromJSON<Out = unknown>(json: unknown): Validation<Out> {
		if (!Array.isArray(json)) {
			throw new TypeError('Malformed validation JSON: expected an array of issues');
		}
		const validation = new Validation<Out>();
		json.forEach((item, index) => {
			const local = new Validation();
			if (
				local.test.is_object(item, 'expected an object') &&
				local.test.has_string(item, 'message', '"message" must be a string')
			) {
				validation.add({
					message: item.message,
					path: Array.isArray(item.path) ? item.path : [],
					code: 'string' === typeof item.code ? item.code : undefined
				});
			} else {
				throw new TypeError(`Malformed validation JSON at index ${index}: ${local.toString()}`);
			}
		});
		return validation;
	}

	[Symbol.iterator]() {
		return this.#issues[Symbol.iterator]();
	}

	get length(): number {
		return this.#issues.length;
	}

	/**
	 * Human-friendly output
	 */
	toString(): string {
		return (
			this.#issues
				.map(
					(issue) => `${issue.message} (${issue.path ? issue.path.map(String).join(' > ') : ''})`
				)
				.join('\n') + `\n(${this.length})`
		);
	}
}
